            steps.push_back(json{{"assistant_turn", step.assistant_turn}, {"results", std::move(results)}});
        }
        json once = json::array();
        for (const AgentSkillUse& skill : transcript.once)
            once.push_back(json{{"name", skill.name}, {"text", skill.text}, {"picture", skill.picture != nullptr}});
